1317				if (con->ucsi->cap.features & UCSI_CAP_CABLE_DETAILS)
1318					ucsi_partner_task(con, ucsi_check_cable, 1, HZ);
1319	
1320				if (UCSI_CONSTAT(con, PWR_OPMODE) == UCSI_CONSTAT_PWR_OPMODE_PD) {
