54	    '--',
55	    'Documentation/'
56	], text=True).splitlines():
57	    # rename
58	    if line.startswith('R'):
59	        _, old, new = line[1:].split('\t', 2)
60	
61	        if old.endswith('.rst') and new.endswith('.rst'):
62	            old = normalize(old)
63	            new = normalize(new)
64	
65	            name = names.get(old)
66	            if name is None:
67	                name = Name(old)
68	            else:
69	                del names[old]
70	
71	            name.rename(new)
72	            names[new] = name
73	
74	        continue
75	
76	    # delete
