95	# redirecting any of those
96	#
97	
98	current_files = set()
99	for line in subprocess.check_output([
100	    'git', 'ls-tree',
101	    '-r',
102	    '--name-only',
103	    args.rev,
104	    'Documentation/',
105	], text=True).splitlines():
106	    if line.endswith('.rst'):
